python3 - <<'PY'
import json, re, sys
from datetime import date, datetime
from urllib.request import Request, urlopen
from urllib.error import HTTPError, URLError

BASE = 'http://127.0.0.1:8123'
CURRENT = ('2026-07-20', '2026-07-26')
PREVIOUS = ('2026-07-13', '2026-07-19')
DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')

def fail(msg):
    print(f'FAILED: {msg}', file=sys.stderr)
    sys.exit(1)

def fetch_range(start, end):
    url = f'{BASE}/orders?start={start}&end={end}'
    try:
        with urlopen(url, timeout=15) as resp:
            status = resp.status
            body = resp.read()
    except (HTTPError, URLError, TimeoutError, OSError) as e:
        fail(f'GET {url}: {e}')
    if not 200 <= status < 300:
        fail(f'GET {url}: HTTP {status}')
    try:
        data = json.loads(body)
    except (json.JSONDecodeError, UnicodeDecodeError) as e:
        fail(f'GET {url}: response is not valid JSON: {e}')
    if not isinstance(data, list):
        fail(f'GET {url}: response JSON is not a list')

    used = []
    for i, order in enumerate(data):
        # Records without a parseable in-range date cannot be used.
        if not isinstance(order, dict):
            continue
        d = order.get('date')
        if not isinstance(d, str) or not DATE_RE.fullmatch(d):
            continue
        try:
            datetime.strptime(d, '%Y-%m-%d')
        except ValueError:
            continue
        if not (start <= d <= end):
            continue
        missing = [k for k in ('order_id','date','region','units','unit_price_cents') if k not in order]
        if missing:
            fail(f'GET {url}: in-range order at index {i} missing fields: {missing}')
        if order['order_id'] is None:
            fail(f'GET {url}: in-range order at index {i} has invalid order_id')
        if not isinstance(order['region'], str):
            fail(f'GET {url}: in-range order at index {i} has non-string region')
        if not isinstance(order['units'], int) or isinstance(order['units'], bool):
            fail(f'GET {url}: in-range order at index {i} has non-integer units')
        if not isinstance(order['unit_price_cents'], int) or isinstance(order['unit_price_cents'], bool):
            fail(f'GET {url}: in-range order at index {i} has non-integer unit_price_cents')
        used.append(order)
    return used

def summarize(orders):
    total_units = sum(o['units'] for o in orders)
    total_revenue = sum(o['units'] * o['unit_price_cents'] for o in orders)
    by_region = {}
    for o in orders:
        rev = o['units'] * o['unit_price_cents']
        by_region[o['region']] = by_region.get(o['region'], 0) + rev
    return total_units, total_revenue, by_region

current = fetch_range(*CURRENT)
previous = fetch_range(*PREVIOUS)
total_units, current_revenue, by_region = summarize(current)
_, previous_revenue, _ = summarize(previous)
if previous_revenue == 0:
    fail('comparison-week revenue is zero; report was not posted')

report = {
    'week_start': CURRENT[0],
    'week_end': CURRENT[1],
    'total_units': total_units,
    'total_revenue_cents': current_revenue,
    'revenue_by_region_cents': by_region,
    'wow_revenue_change_pct': round((current_revenue - previous_revenue) / previous_revenue * 100, 2),
}
payload = json.dumps(report, separators=(',', ':')).encode('utf-8')
req = Request(f'{BASE}/report', data=payload, method='POST', headers={'Content-Type': 'application/json'})
try:
    with urlopen(req, timeout=15) as resp:
        status = resp.status
        response_body = resp.read()
except HTTPError as e:
    fail(f'POST {BASE}/report: HTTP {e.code}')
except (URLError, TimeoutError, OSError) as e:
    fail(f'POST {BASE}/report: {e}')
if not 200 <= status < 300:
    fail(f'POST {BASE}/report: HTTP {status}')
print(json.dumps({'status': status, 'report': report}, separators=(',', ':')))
